SELECT n.*, u.real_name AS receiver_name
FROM notification n LEFT JOIN user u ON n.receiver_id = u.id

    AND n.receiver_id = #{receiverId}
    AND n.is_read = #{isRead}

ORDER BY n.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM notification

    AND receiver_id = #{receiverId}
    AND is_read = #{isRead}
